quests[77794] = { id = 77794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Dream Reward" }
quests[77795] = { id = 77795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenged Artifacts", objectives = "If you have supplies, I have wares. Old things. Some sacred things.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77802] = { id = 77802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Do I Call You?", description = "Guardian! Or... teacher! Parent?\n\nI want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own.\n\nI want to tell them that I do not have a druid. I have you!\n\nTell me what title you prefer.", progress = "I have heard so many titles from the druid Creekward. I am certain we can come up with something far more interesting.", completion = "What an excellent title! I will use it as often as I can.\n\nThank you.", objectives = "Speak with Dionaessa to choose a title in the Root-Bound Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77813] = { id = 77813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Strikes", description = "<Flaps does a spin and deposits a drool-soaked note into your hand.>\n\nAh, {name}. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself!\n\nI would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.", completion = "Hello again, {name}. Now, let us see about this gryphon!", objectives = "Meet Lord Andestrasz at the Skytop Observatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77815] = { id = 77815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Race Tour", completion = "Well done! This storm gryphon is indeed an impressive creature. May you share many wondrous adventures!\n\nFair skies and strong winds, {name}.", objectives = "Fly each of the Storm Race courses around the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77818] = { id = 77818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cruel", description = "Primalists, djaradin, and Druids of the Flame all work together against us.\n\nBut I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.", completion = "I am glad you made it out. We have no choice but to retreat to the tree, before Fyrakk's forces arrive.\n\nAnd Elder Cassaphine... I fear that she has already been lost to this prophecy of flame.", objectives = "Help Merithra close the flaming portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77822] = { id = 77822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titanic Mold", description = "<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>", progress = "By the forge, did you actually do it? Did you find the Titan Key mold?", completion = "I cannot believe it, {name}! We simply must reforge the key now that we have the mold.\n\nI'll need to make preparations. The tome that Tithris gave me described an involved process. Magical rituals, special components, that sort of thing. I may need you help once I have all my irons in a row.\n\nI'll send word when I'm ready for the next step.", objectives = "Return the Titan Key Mold to Weaponsmith Koref in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77829] = { id = 77829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging a Legend", description = "There you are! Weaponsmith Koref was just looking for you. Left me with a note asking you to meet him in the Obsidian Conclave.\n\nSounds like you're helping him reforge an ancient titan key? Let me know how it goes! That's headline news if I ever heard it.", completion = "We'll need rare materials for the key. Some special gold dust and flux. You'll find them both in the Waking Shores.\n\nAfter you find the materials, meet me at the Earth-Warder's Forge in the Obsidian Citadel. That's where I'll forge the Titan Key. And take my place amongst blacksmith legends, should my anvil strike true.\n\nHere, this note that has all the details. We're so close, {class}!", objectives = "Seek out Weaponsmith Koref in the Obsidian Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77831] = { id = 77831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Key To Reforg(ing)", description = "You have the final materials! Perfect.\n\nI prepared the forge and the mold. I just need you to add the ingredients when I say.\n\nOh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!", progress = "The Titan Key. By the forge... Let me have a look.", completion = "This is amazing! And it's already cool to the touch? What incredible magic.\n\nHmm. There's writing on the shaft. I don't recognize most of it, but this is Tyr's symbol. I'll create a quick sketch of the rest of the entire message and see what I can find out.\n\nI'd say the key is safest with you. Besides, what's a key without a lock? And if anyone can find a titan lock in need of opening, it would be you.", objectives = "Assist Weaponsmith Koref in reforging the Titan Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77832] = { id = 77832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows upon shadows", description = "I need to save him.", objectives = "Slay the Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77833] = { id = 77833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Concentrated Sophic Vellum", description = "I know of a sage who can help temper Fyr'alath. Shalasar Glimmerdusk is an expert in intellectual matters, often pondering theories for controlling volatile magics. Few understand sophic matters as well as she does.\n\nSeek her guidance in managing shadowflame. I suspect her solution may include a sprinkle of Chromatic Dust!", completion = "Ah, yes! Thank you for making the journey here. \n\nOthers warned me not to isolate myself from academia, but I knew being sequestered in this remote natural locale would come in handy someday.", objectives = "Seek out Shalasar Glimmerdusk in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77835] = { id = 77835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Rune of Shadowbinding", description = "Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them.\n\nIf there is anyone who can assist in binding Fyr'alath's power, it's her.", completion = "You want to bind shadowflame? How dangerous! How daring! Let's do it.\n\nI've been studying flora in the Emerald Dream. Studying the realm's exotic and dreamlike plants is quite distracting, but I've seen one in particular that could help us find some answers.", objectives = "Seek out Lydiara Whisperfeather in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77838] = { id = 77838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tattered Dreamleaf", description = "The properties of Dreamleaf are foreign to you. \n\nCompleting events during the Superbloom will give you the knowledge necessary to help your ally.", completion = "Shadowed Dreamleaf still remains perplexing but hopefully your ally could still use this knowledge.", objectives = "Complete events during the Superbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77839] = { id = 77839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Kingdoms Cup Circuit", description = "It is once again time to test your mettle.\n\nMy bronze colleagues have traveled to the Eastern Kingdoms to create new racing challenges. Many racecourses await you across the continent.\n\nAre you up to the task?", progress = "Have you taken wing today?", completion = "You lead the way among your fellow skyriders! As the Eastern Kingdom Cup continues, find other races there and prove you are a cut above the rest.", objectives = "Fly through the introductory Eastern Kingdoms Cup courses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77840] = { id = 77840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77841] = { id = 77841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera Invitational", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
