quests[77845] = { id = 77845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera Invitational - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77865] = { id = 77865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Burial", objectives = "Today you'll be returning a Maruuk Burial Banner. Truth be told, I almost feared that someone had stolen it. Again! But after searching the entire tavern, I went to double-check my locker and found it safe and sound!\n\nThe stress of these recent events seem to be getting to me... \n\nPlease, speak with Sansok Khan in Maruukai and return the banner to where it belongs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77867] = { id = 77867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moruud" }
quests[77869] = { id = 77869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Echo Isles", description = "{name}, there appears to be trouble in the Echo Isles.\n\nRokhan has requested your help.", completion = "It is good you be here, {name}. Trouble is brewin'.", objectives = "Meet with Rokhan in the Echo Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77871] = { id = 77871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Old Loa", description = "Bwonsamdi does not be visiting in person without a good reason. Listen to all he has to say. \n\nDen we think, den we act.", progress = "What Bwonsamdi be saying is very serious. Mueh'zala worship is a bloody one.", completion = "De Darkspear always be worshipping multiple loa, but Mueh'zala? We can do better.\n\nOur path is obvious.", objectives = "Hear Bwonsamdi's message to the Darkspear trolls and find a solution.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77874] = { id = 77874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Loa of de Past", description = "We need to be findin' de old loa and call dem back. There must be a way to find where dey went. \n\nIf we can find de old loa, we can host a Trial of the Loa to reconnect with their power.\n\nBwonsamdi said dey are still out there. I think he be dropping a hint for us...", completion = "I be feelin' somethings eyes on us. Judgin'. Dis loa be clever, but so are we.\n\nLet's continue.", objectives = "Find a guide to one of the lost loa by making a proper effigy, and follow the guide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77877] = { id = 77877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One with the Loa", description = "Pieces of Lukou be scattered.\n\nBut her heart be deep inside the ogre mound.\n\nDe shadows can take us there. Quietly. Quickly. Speak to me when you are ready.", progress = "Kevo ya Siti wants to bring us inside the mound.", completion = "Dat was... somethin' else. Feels like my stomach still be outside!\n\nBut we be having work to do.", objectives = "Talk to Kevo to be taken inside the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77878] = { id = 77878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy of Winter" }
quests[77879] = { id = 77879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Stalker", description = "If dis loa be huntin' here, he may have seen us already. Since we don't know for sure, let's split up.\n\nI be hunting for him, while ya get his attention. Jani says the loa has been taking the offerings meant for Hakkar, the loa of blood. \n\nBut we don't know WHY. Collect some and see if he wants them. If his motive is something else... we be knowin' soon enough.", progress = "<Kevo ya Siti examines your offerings.>", completion = "<Kevo ya Siti accepts the offerings silently.>\n\nI don't be wanting dese offerings myself. Slowing Hakkar's return benefits us all.\n\nIt will take more than just remembering. Your hunt is just beginning.", objectives = "Collect 6 Offerings to Hakkar to attract the loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77880] = { id = 77880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Lukou", description = "Dis be the last place Kevo ya Siti sensed Lukou.\n\nWe be needing to ask around, see who knows where she might have gone.", progress = "With enough information, we can track Lukou down.", completion = "It be time to find Lukou.", objectives = "Ask about Lukou and follow the trail to find her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77881] = { id = 77881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There is Another", description = "If Mueh'zala be involved... I will help. But for a loa trial fit to push Mueh'zala out, we will need another.\n\nOur sister loa is also lost. We were a team, her and I, until disagreement pushed us apart. Lukou is the loa of regeneration. She be the ideal loa to balance against death.\n\nI owe her an apology. You are here, and it be time.\n\nI last sensed her presence near the small settlement of Bambala. I be meeting you there.", completion = "This place is not how I remember it.\n\nAnd I do not feel our sister. I will need to get closer to where she is.", objectives = "Go to Bambala to seek out Lukou.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77882] = { id = 77882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen but Not Forgotten", description = "There be many pieces missin' from dis altar. We be needing to repair it so dat Lukou is not angered when she returns, Lukou must see dat we are on her side.", progress = "We need all the pieces you can find.", completion = "Got dem all?", objectives = "Collect 8 altar fragments from around the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77885] = { id = 77885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream Wardens" }
quests[77886] = { id = 77886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Shadowed Dreamleaf", description = "When Fyr'alath's power is at its limit, you will need a grip that can cool itself. It is like standing your ground when a beast charges you: as the battle heats up, you need a way to stay focused.\n\nVarious leathers throughout the Dragon Isles have that cooling property, but I know of something better. Foliage that is routinely exposed to shadowflame would be the best choice for binding the components together. Let us gather what you need.", progress = "Did you find what we need?", completion = "Excellent.\n\nYou hunt for something long enough, you will always find it. I am glad we found precisely what you needed.", objectives = "Collect Shadowed Dreamleaf from completing objectives in the Superbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77889] = { id = 77889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fiery Proposal", description = "Ah hello!\n\nI have been working with some inscribers recently. We've been making a new type of ink. It's like fire ink, but even fierier! \n\nWe need fiery essence from fire elementals, and fire elementals are currently attacking the dream. I believe this is what is called a \"win win\" scenario.\n\nPlease drop their essence off at my associate in Amirdrassil.", progress = "New knowledge can come from the strangest sources!", completion = "Ah, wonderful. I will pass these on. \n\nThank you, {name}.", objectives = "Collect 10 Fiery Essence from fire elementals in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77891] = { id = 77891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fixing The Dream", description = "Engineering is an exact science! When something explodes, engineers plan it that way. \n\nDreams are not exact, especially emerald ones! Someday, someone will want engineers to fix the Dream, and we won't know how to do it. We need a lot more information to understand what we're dealing with!\n\nGo to the Dream and place research beacons at my designated points. They will gather the information needed for any future repairs. Use this handy teleport device if you want to find the locations quickly.", progress = "I wonder if we'll ever truly understand the dream.", completion = "So much useful data about the dream, it will keep the engineers busy for years.", objectives = "Activate 8 Research Beacons", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77892] = { id = 77892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearls Of Great Value", description = "When Amirdrassil's roots spread to the water, many rare creatures arose from the ocean's depths and now flourish around the dreams.\n\nOne such rare creature is the Sandsparkle Clam, which can contain magical pearls!\n\nSee if you can locate these clams and find some pearls within.", progress = "Have you found any pearls?", completion = "Fascinating, {name}, there is great potential in the power of these pearls.", objectives = "Collect 10 Sandsparkle Pearls", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77894] = { id = 77894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Lukou", description = "I was hoping we'd be getting more pieces than dis, but we make do with what we got, eh?\n\nCall Lukou to de altar. Hopefully she will answer.", progress = "We're close!", completion = "Thanks for the help, {name}. I was not harmed badly.", objectives = "Summon and speak with Lukou at the altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77896] = { id = 77896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sleepy Search", description = "In our fight against Fyrakk's forces, a group of my fellow druids went out in search for a quiet and safe place to rest. But with Fyrakk's forces closing in on their location...\n\nI have to start planning for another assault, I can't split my time as much as I wish. \n\nI last saw them heading south to a cave by the shore. Please, I just need to make sure they're safe.", completion = "Have Fyrakk's forces attacked us? \n\nAs you can see, there is no issue with that here. \n\nHowever, I do have a much bigger problem on my hands.", objectives = "Check up with the sleeping druids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77897] = { id = 77897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Book", objectives = "Well, if it isn't my trusty investigator. \n\nThere's a contact in the Kirin Tor who owes me a favor. They gave me a tip about a book in Karazhan that might help us decipher those tablets you recovered. You know, the ones from the Azure Span and Shifting Sands?\n\nBut we both know you're the one with the securing skills here. Here's the note my contact left. Should help you find the book!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77898] = { id = 77898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Tribute", description = "It be time to return home. Let us welcome dese loa to the Echo Isles. Their positive influence should make short work of Mueh'zala's presence.\n\nGo ahead, I be right behind ya.", progress = "The offerings need to be set exactly right.", completion = "All de offerings be set. Let's do de next step.", objectives = "Set up the loa altars at Darkspear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77899] = { id = 77899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rush'kah", description = "When we make de rush'kah, we recreate de shape of the loa as we be seein' dem in our mind. By knowing the shape of de loa, we better understand who dey are. But de mask be shaped by our hands, so when de loa sees it, dey know what we expect dem to be. \n\nIf the loa don't bless the mask, we expect dem to be something dey will not be. If de loa bless de mask, dey like what we see in dem and a bargain can be struck. \n\nWe could just write a contract, but it is easier to lie with words than with your hands.", progress = "De rush'kah be important in bonding with the loa.", completion = "Good work, {name}!\n\nAlmost done with mine here.", objectives = "Make a rush'kah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77900] = { id = 77900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loa Trials", description = "When de loa bless the rush'kah, de trials will begin. Loa be giving tasks to teach us. Once de trials start, dey don't stop for nobody!\n\nLet's go to de altar together. Witch Doctor Tzadah will lead us in de ritual. She be Master Gadrin's apprentice, but be showin' real initiative in helping out on the trial.", progress = "It is time to begin de trial.", completion = "Dis trial be... something different, now. Normally, de loa grant visions or give tasks to teach and connect with us.\n\nInstead, we work together to stop Mueh'zala.", objectives = "Start the trial at the Altar of Darkspear Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77901] = { id = 77901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retraining the Trainees", description = "Your witch doctor is trying to twist the trial to empower Mueh'zala. Many will be enthralled by this power, but we still stand with the Darkspear.\n\nI had a different trial in mind. Now, we adapt. Free your fellow trolls from his sacrificial magic. Dis charm will help them, but you must weaken them first.\n\nTry not to sacrifice dem.", progress = "Use the charm on the trainees after you weaken them!", completion = "This will reduce the ritual's power. Mueh'zala does not get to claim more Darkspear!", objectives = "Extract 8 shadows from lost trainees after weakening them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77902] = { id = 77902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Recovery", description = "Dat witch doctor has stolen de trial. She mocks us, trying to eat de life of living things to free Mueh'zala. We still have influence over it, though. \n\nTogether, we will overwhelm her evil circles. When you find a circle, call upon me, and we will push death aside.", completion = "When you are fighting death, Lukou is a good ally.", objectives = "Remove 3 ritual circles with Lukou's aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77903] = { id = 77903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Power of Death", description = "De trial can't be stopped after it starts, but we won't let Tzadah use our people or our loa to aid Mueh'zala.\n\nIf we be doing nothing, even more Darkspear could be swayed to find power in Mueh'zala. I'll look for a way to breach Tzadah's protective energy, you stop the spirits from taking over our home!", completion = "Good work with those minions. Dat will keep them off our backs for what be ahead.", objectives = "Kill Mueh'zala's summoned spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77905] = { id = 77905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avatar of Mueh'zala", description = "It be down to dis moment: working with our loa to save de soul of de Darkspear.\n\nSee if Jani has found anything. Hopefully, his item will let you get close enough to Tzadah's effigies to destroy dem. That should give us a chance to strike the Witch Doctor herself. I'll occupy her attention with Kevo ya Siti's aid, but watch out for her guardians. Dey won't let you destroy her effigies without a fight.", progress = "Tzadah is a disgrace to the Darkspear.", completion = "We defeated Tzadah. She can no longer aid Mueh'zala's attempts to escape his prison. \n\nWe could not have done this without de aid of de loa. Lukou, Kevo ya Siti, and even Jani.", objectives = "Collect Jani's blessing and then travel with Lukou to the top of the pillars to defeat Tzadah's protection totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77906] = { id = 77906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Darkspear Loa", description = "Dat was not a traditional trial, but we only keep tradition if it be helping de tribe.\n\nIt be our strength: to adapt to what comes.\n\nIt be time to shed de past and honor those most important to us. De Darkspear was never de largest tribe, nor de strongest. We endure because we choose our path, and our allies, well.\n\nDese loa and you all worked and sacrificed not just to help Bwonsamdi, but to protect de souls of de Darkspear. Dat be why we honor our loa... and you.", progress = "The effigies need to reflect our favored loa.", completion = "De Darkspear don't just serve a loa because dat loa be strong. De Darkspear serve loa who serve de tribe. \nDat be what Lukou, Kevo ya Siti, and Jani did. So we honor them now.\n\nDe mask you made was not just for de ceremony. Take it, and de raiment of our tribe. \n\nWear them and know you are Darkspear.", objectives = "Destroy Mueh'zala's altar and add Jani's.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77908] = { id = 77908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legacy of Secrets", description = "<Return the book to Bobby Carlisle in Valdrakken to assist with deciphering the tablet text!>", progress = "Was my source any good? Were you able to find the book?", completion = "Of course you found it! You know, you could have a real future as a field investigator.\n\nTyr's Legacy, huh? Interesting. I'll start working with Kathos to see if we can decipher any of the text on those tablets. I'm sure this book is the key.\n\nWe're getting so close! I can already see the headlines.", objectives = "Return the book, Tyr's Legacy, to Bobby Carlisle in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77910] = { id = 77910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Shrubbery", description = "Certain plants from the Emerald Dream could contain ingredients that would be helpful in our work here, but we need a lot of them, and I'm not hiring some herbalist to collect them.\n\nI've enchanted a water pot to help solve the problem. \nTravel to the Emerald Dream and use it on the plants I require. The plants should then deliver themselves.", progress = "Have you found the plants?", completion = "Excellent work, these plants certainly do spruce up the place!", objectives = "Use the Watering Pot on 12 Enchanted Shrubs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77911] = { id = 77911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build-a-Blanket", description = "I am unable to rest! I have spent all my energy in battle, but there is too much noise and the ground is too hard for me to sleep...\n\nI know! It pains me to ask this, but I need to rest so I can go back out and fight.\n\nCould you feed two birds with one seed for me? Take out the enraged lashers and retrieve their leaves so I can make a blanket to rest on.", progress = "For the Emerald Dream, it sure is quite chaotic here.", completion = "Thanks for the leaves. Hopefully this will help me fall asleep.", objectives = "Collect 6 Velvety Lasher Leaves from lashers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77912] = { id = 77912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unmodern Jewelry", description = "Some of the local Jewelcrafters are looking to study examples of the Zaqali tribes adornments.\n\nGiven they are currently attacking my home, we may take advantage of the situation.\n\nI thought you might take them violently, yes?\n\nArgonax waits once you have collected them.", progress = "New knowledge can come from the strangest sources.", completion = "I was not expecting these so soon. \n\nYou do work fast, {name}.", objectives = "Collect 10 Zaqali Adornments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77914] = { id = 77914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Runes", description = "I am told that the Druids of the Flame help to stabilize their portals into the dream through the use of a unique sort of inscription! While their ends are abhorrent, I cannot help but be curious as to their means.\n\nIf we can better understand their methods, then perhaps we can better equip our allies to stem the tide of their arrival. If you get your hands on any burning runes, could you bring them to my colleague for further study?", progress = "Take care, friend. I doubt the Druids of the Flame will part with their runework willingly.", completion = "You have my thanks. We will endeavor to decipher these forthwith.\n\nThank you, {name}.", objectives = "Collect 10 Burning Runes from druids of the flame in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77922] = { id = 77922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluffy Filler Retrieval", description = "There is no way I could rest without something soft to sleep on. Luckily, the dream has some sage so plush, that it would even put roc feathers to shame! It would be a perfect filling! \n\nCould you collect some sage around the area for me to rest on?", progress = "The sage should be soft enough to make a comfortable place to sleep. Thank you for your assistance.", completion = "Thanks for bringing back the bed filling.", objectives = "Collect 8 Silky Sage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77928] = { id = 77928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Are Always Listening", description = "Remember my contact, Fangli Hoot? Seems she has another theory about the one behind these artifact thefts.\n\nI'm a bit weary after the last tip went nowhere, but we can't turn down a lead. Journalistic integrity demands we at least hear her out.\n\nYou'll find her by the barber shop.", completion = "Ok, this time I'm sure. I tracked everyone, yes everyone, even you.\n\nTithris is behind everything. He's been meeting with shady characters all over the city to secure supplies for something big. My guess is an expedition. \n\nYou need to investigate several caches of his purchases. I noted coordinates for the general locations. Put that thinking cap to work! And that idol of yours can help you narrow in on their exact location.", objectives = "Speak with Fangli Hoot near the Valdrakken barber shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77932] = { id = 77932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmth of Life", description = "The Druids of the Flame practice virulent magics that warp and burn all they touch. They do, however, have excellent taste in alchemical reagents.\n\nIf you should happen across any of their metamorphic ash, could you gather it up for me? One of my contacts within the Dream has been asking after the stuff.", progress = "Ah, there you are! Have you managed to get your hands on any of that ash, yet? Its alchemical properties are truly wondrous.", completion = "Ah, wonderful! The things I will be able to accomplish with this... One does not simply walk into the Firelands, after all!", objectives = "Collect eight samples of Metamorphic Ash from Druids of the Flame in the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77933] = { id = 77933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbling Discoveries", description = "The rise of Amirdrassil has unlocked various geological wonders in the dream. Among these are a variety of magical springs, bubbling water from deep within Azeroth.\n\nTravel the dream and gather samples from these springs.", progress = "Have you gathered the samples?", completion = "I shall share these with the others here, after sampling them myself.", objectives = "Collect 8 samples from Bubbling Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77934] = { id = 77934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Complete Inventory", description = "<Compile your notes on the caches for Fangli Hoot in Valdrakken.>", completion = "Hmm, nothing unusual. Still, I'm convinced this is our drakonid. Why would a simple innkeeper be meeting up with so many shady characters?\n\nI need to recheck my data and look through what you brought me. Maybe something will pop up.\n\nWatch yourself, {name}. I may be paranoid, but I'm not blind. We're running out of time.", objectives = "Report your findings to Fangli Hoot near the barber shop in Valdrakken.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77935] = { id = 77935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A-Sword-ed Needs", description = "Swords!\n\nSorry, I saw you and I did not want to forget.\n\nYes. We need swords. In the Dream. You can provide, yes?\n\nPlease deliver them to Cylania.", progress = "Can I help you?", completion = "We will put these to good use. \n\nThank you, {name}.", objectives = "Deliver 3 Draconium Swords to Cylania in the Emerald Dream", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77936] = { id = 77936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warm Harvest", description = "Everyone knows heat plays a critical role in blacksmithing.\n\nI hear the Emerald Dream is still heavily under attack by allies of the flame. There must be a way to harvest fuel from those eternally fiery creatures.\n\nIf you do secure anything, I'm sure one of the local blacksmiths in the Dream will be very interested.", progress = "Hmm. Yes?", completion = "You've faced dangerous enemies to acquire these materials. Thank you. This will prove mightily useful for crafting our own devices.", objectives = "Collect 10 Essence of Endless Flame in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77937] = { id = 77937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Sugar", description = "During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies.\n\nTo the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver.\n\nHowever, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.", progress = "The enchanters would love to have more for testing. They must use and test it wisely. We hope the flower will persist even after the great bloom, but no one can know for sure.", completion = "Ahh--I thought you had brought me fresh baked cookies! But this is even better.", objectives = "Collect 8 Glowdrop Sugar from Shaded Glowdrops in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77938] = { id = 77938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unlikely Engineer", description = "I hear there is a legendary engineer in the Dream who crafts the most beautiful dream catchers.\n\nThis engineer, Nyla Bushtail, enjoys acorn-flavored morels and relies on them to fuel her work. Acorn-flavored mushrooms... certainly strange, but perhaps not unheard of.\n\nThere's a coastal area close to the Eye of Ysera where these morels grow abundantly. Do tread carefully around any wildlife in the area. If these morels are as tasty as I hear, they will be guarded greedily.", completion = "<Nyla Bushtail, a fluffy, bright-eyed Fol'ya, accepts the morels with small paws. She tucks them away into a stash nearby, her movements fluid and tidy.\n\nThis must be the legendary engineer who loves acorn-flavored mushrooms. It all makes sense now.>", objectives = "Collect 8 Whiteburr Morels for Nyla Bushtail in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77945] = { id = 77945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boots on the Ground", description = "Just who I wanted to see.\n\nI have a requisition script for items of leather from some of the denizens of the Dream. Shoes, of course. Bipeds tend to go through them like a bird through the forest, yes?\n\nOnce you have acquired them, please take them to Cylania.", progress = "Can I help you?", completion = "Wonderful, thank you, {name}. \n\nYou can never have enough boots.", objectives = "Deliver 3 Pioneer's Leather Boots to Cylania in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77946] = { id = 77946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fibrous Thread", description = "Fine thread may conjure images of tailory, but it can serve a vital role in leatherwork as well.\n\nSome of the Dream's hardier flora can be processed into a thread strong enough to secure even the thickest of hides and scales. If you happen upon any dense fiber during your travels, you would be well-served by bringing it to my colleague in the Dream.", progress = "You needn't worry about the plants themselves. They are nigh impossible to harm, and so long as they are treated respectfully, they will be more than happy to share their bounty with you.", completion = "Ah! This is precisely what I needed. You have my thanks, {name}.", objectives = "Bring 1 Emerald Fiber from Enchanted Thickets in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77947] = { id = 77947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primalist Fashion", description = "Ah, {name}, there you are!\n\nThe robes of the primalists make for interesting study for the local tailors. If you could retrieve some from the primalists assaulting the dream, I would be pleased, yes?\n\nNo rips or tears please. Blood stains optional. They can be washed out.", progress = "Can I help you?", completion = "Magnolia mentioned you would be dropping off some robes.\n\nAh, she also mentioned they may need to be washed.\n\nThank you, {name}.", objectives = "Collect 10 Intact Primalist Garb from the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77948] = { id = 77948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Out", description = "Please, I know how this looks, but we are on the same side!\n\nMy siblings and I intended to defect from the Flame together. However, none of them have escaped or met up with me since I left, and it's been days! I fear the worst.\n\nDo you think I would be begging for aid, alone and unarmed, if I was not honest? Please, find them. They are all I have left.", completion = "<Solarys's face falls, clouding with grief at your explanation.> \n\nFinite moments with my family are worth more than an eternity of regrets. Life itself is worth more than that, but my pleas fell on deaf ears.\n\nThank you for saving what little of my family is left.\n\nOne of the little creatures Kery'nael helped saved seems to have taken a liking to you. Please take them. It's the least we can offer the poor thing.", objectives = "Find Solarys's siblings in the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77949] = { id = 77949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashion Feathers", description = "Much of the Dream's wildlife is feathered or furred. Their shed, whether it be down fur or feathers, is reputed to be extremely durable, soft, and fashionable.\n\nThe great somnowls' feathers are particularly desirable. They don't shed often, and feathers are quickly retrieved by local wildlife for nest building.\n\nI've heard that your best chance is scouring the Meandering Rootlands in the Dream.", progress = "Have you found any feathers? They're easy to identify. As large as two hands lengthwise, often snowy in color, and buttery soft.", completion = "Tailors from all over the world will be delighted to have these!", objectives = "Collect 10 Shed Great Feathers in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77953] = { id = 77953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sphere in Danger", objectives = "Here's the note they sent. Something to do with an orb? \n\nKathos had to run out to check on something, so you can bring the orb back to me. I'll make sure to hand it over upon her return.\n\nStay safe out there. Oh, and don't forget all of your useful tools!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77954] = { id = 77954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Orb", description = "<Tithris told you to return the orb to him in Valdrakken. He will pass it to Preservationist Kathos.>", progress = "You got that orb for me? For Kathos, I mean.", completion = "Perfect. I'm sure Kathos will be mighty glad to see this. She said the orb will help your investigations.\n\nWhy, there she is right now! Glad to see her back safe. I'll hand over the orb soon as I'm done with getting something from the back.\n\nThanks for the hard work, {name}!", objectives = "Return the Orb of Rathmus to Tithris in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77955] = { id = 77955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heated Hearthstone Hustle", description = "Wait, my hearthstone! I can't sleep without my hearthstone. \n\nA djaradin stole it during our last battle. It stays warm perpetually and I always sleep with it. \n\nI hate that I must ask more of you, but could you get my hearthstone? \n\nThe djaradin that stole it should be near Fyrakk's army, just north of here.", progress = "My eyes grow tired, but my body is still awake...", completion = "Gah! I still can not fall asleep! I am embarrassed to ask but there is only one option left.", objectives = "Retrieve the Heated Hearthstone from the Stonewarmer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77957] = { id = 77957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Treacherous Race", objectives = "Bobby and I finally deciphered the tablets. They tell of an artifact of immense power that was locked away in Tyrhold. And I fear Tithris is after whatever that artifact is. \n\nYou must secure whatever the tablets speak of before Tithris. Bobby and I will find a guard and join you as soon as we can.\n\nTake our notes. There are many safeguards that you will need to get through to find the artifact's vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77958] = { id = 77958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleepy Druid in Emerald Dream", description = "Why can I still not fall asleep, even with a heated blanket? \n\n<Thaalean curses the air then sighs.>\n\nThis is embarrassing to request, but my mother used to sing me a lullaby before I slept back in Teldrassil, may I ask you to do the same?\n\nAny lullaby will do, I just want to rest peacefully.", completion = "Thank you so much for checking on my friends. \n\nWhen they reawake, we will be ready to fight Fyrakk's forces once more.", objectives = "Sing a lullaby for sleepy druid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77976] = { id = 77976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Dreamsurge", description = "A group of druids from across Azeroth have gathered to investigate a sudden surge in energies coming from the Emerald Dream.\n\nThis has the potential to affect us all, {name}. Please aid them in their endeavor to understand this new phenomena.", completion = "Thank you, {name}, for your assistance. We will have to keep a close eye on this Dreamsurge as it develops.", objectives = "Meet the druids investigating the Dreamsurge and gather one hundred Dreamsurge Coalescence. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77977] = { id = 77977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ominous Artifact", description = "<An orb would fit perfectly atop the console.>", progress = "A chest! Locked away in Tyrhold all this time. Can I examine it?", completion = "The text on top of this chest is definitely titan. But here, this is a language used by the Burning Legion! And this text is used by servants of the Old Gods. I've never seen these three languages being intermingled like this.\n\nI'm not fluent, but the titan text speaks of a danger within the chest. An item? Or perhaps just... knowledge.\n\nMy order will see that the chest is secured and studied. Thank you again, {name}. In my eyes, you're an honorary Preservationist at this point.", objectives = "Secure the Orb of Rathmus as well as the artifact it is hiding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77978] = { id = 77978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Passed Torch", description = "<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> \n\n<It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>", progress = "What is it?", completion = "Lyandris saved all this? And you... you finished what she started.\n\nThank you for returning her journal to me. Keep the documents. They will provide valuable information to you and your allies. \n\nThey would only be a grim reminder to me.", objectives = "Collect documents and kill Druids of the Flame within the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77982] = { id = 77982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greedy Gessie" }
