quests[77988] = { id = 77988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n: Tranform into an adult and gain improved speed.\n: Restore 1 Vigor until all Vigor has been recovered.\n: Resets cooldowns.", objectives = "Help Zhusadormu glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
