quests[78113] = { id = 78113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenge Tour", description = "Hello again adventurer!\n\nDo you like a challenge? I hope so as my bronze colleagues have a new set of challenge courses for you to fly.\n\nMake no mistake, these will be more difficult than the previous courses. All the obstacles remain but there none of the boons waiting for you along the route.\n\nAre you up to the challenge?", completion = "Well done! You are truly mastering the art of dragonriding.", objectives = "Complete a challenge course in every Dragon Isles area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
