quests[78126] = { id = 78126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightbringer's Duty" }
quests[78128] = { id = 78128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotta Go Fast", description = "You're interested in proving yourself alone, eh? I have a challenge for you then, good luck!", progress = "There's still a task for you to complete.", completion = "Well enough, you've completed what I've set you off to do.", objectives = "Complete a match of Battleground Blitz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78129] = { id = 78129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotta Go Faster", description = "You survived that easy test.\n\nThere's more for you to prove. Try again and return when you are finished.", progress = "Huh, not quite there yet.", completion = "You've shown you have some endurance. I suppose that is adequate.", objectives = "Complete 3 matches of Battleground Blitz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78131] = { id = 78131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78153] = { id = 78153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Prototype Rune", description = "Ah, I see! We're in uncharted territory here, but I've got a plan.\n\nYou'll need some Cosmic Ink, Runed Writhebark, and Shadowflame Essence.\n\nSharing this recipe with a friendly scribe should allow them to complete a Crafting Order for you. Let me update my notes with a recipe for the Rune of Shadowbinding.", progress = "Is it ready? Shall we proceed?", completion = "Perfect! Of course, we aren't finished yet. We'll need to strengthen the binding if we're to have any hope in making Fyr'alath accept our modifications.", objectives = "Craft or obtain Lydiara's Binding Rune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78154] = { id = 78154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Test: Rune of Shadowbinding", description = "We need to finalize the binding. We can attune the components properly by testing them in combat against Fyrakk's most powerful lieutenants. Then we can bind the attuned materials to Fyr'alath.\n\nIf you can defeat Gnarlroot, Igira the Cruel, and Volcoross while this rune is bound to them, you'll be ready to fully attune the Rune of Shadowbinding.", progress = "A hero never backs down from a challenge. You've got this.", completion = "How exciting! I'm more of a crafter than a fighter, but your martial skills are quite impressive!", objectives = "Defeat Gnarlroot, Igira the Cruel, and Volocross in Amirdrassil, the Dream's Hope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78155] = { id = 78155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Radiant Fleck of Ash", description = "I've heard that in the Emerald Dream, a coarse ash with strong properties of shadowflame tends to cling to powerful pieces of equipment. The only way to harvest that powerful dust is by disassembling the equipment. \n\nHere, use this rod I've enchanted. It should allow you to siphon off the dust you need.", progress = "Don't give up! This process doesn't just help with crafting. It builds character! Remember that!", completion = "I hope the dowsing rod helped! Now for our next step...", objectives = "Collect Radiant Flecks of Ash from powerful pieces of gear throughout the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78156] = { id = 78156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Radiant Vellum", description = "We can refine my creation by embedding the enchantment with Order magic. \n\nHere are my notes on Concentrated Sophic Vellum. Sharing this with another friendly enchanter should give them enough info to complete a Crafting Order for you.", progress = "I've seen students become... disenchanted... with this type of task, but I know you're made of sterner stuff.\n\nSorry. I've been in isolation for a long time, and I don't get to use that \"joke\" very often.", completion = "We're almost there. Now we just need to coax the competing shadowflame and Order magic to cooperate.", objectives = "Craft or obtain Shalasar's Sophic Vellum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78159] = { id = 78159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Glowspore Grip", description = "To craft something workable, we'll need a substantial amount of Zaralek Glowspores and some leather.\n\nHere are my notes on the Symbiotic Glowspore Grip. Sharing this with a friendly leatherworker should give them enough info to complete a Crafting Order for you.", progress = "Tracking this down is a lot of work, but the quarry is worth the hunt.", completion = "Time for the final step. This might be a little... unpleasant.", objectives = "Craft or obtain Erden's Glowspore Grip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78160] = { id = 78160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Test: Symbiotic Glowspore Grip", description = "You will have to trust me. We need to activate the reagents embedded in the grip.\n\nWrapping the grip around Fyr'alath's haft should work, as long as you can survive the onslaught that follows. You're going to need to make adjustments as you go, and you won't get it the first time. The spores need to adapt to the axe.", progress = "Keep at it. All this hard work is going to pay off.", completion = "Good work. This grip should serve you well.", objectives = "Empower the grip while surviving its union with Fyr'alath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78162] = { id = 78162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzu's Distraction", description = "Truly your questions are important to me. Alas, I am simply too distracted. \n\nThese podlings--nasty little ones. I'm sure you've seen them. They're encroaching upon my nest and just a total nuisance. \n\nBothering myself and my friends? The nerve! Here's my feather. Why don't you go change these nuisances into something less bothersome.", progress = "I can still hear the annoying sounds of those podlings. It's torture.", completion = "You again? You did what? Oh, yes. That's fine.", objectives = "Weaken 8 podlings, then use Q'onzu's Faerie Feather to change them into Faerie Dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78163] = { id = 78163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzu's Qualification", description = "You seek an audience with Q'onzu but bring no offerings? \n\nOne does not just walk up and speak to the loa of Change, I'm afraid. You must first prove you are worth their time.\n\nThe friends of Q'onzu have been granted one hundred questions by the loa themself! You must prove your wit and answer each of them true.\n\nReturn to me if you answer all one hundred. Then perhaps you'll earn an audience.", completion = "You were actually going to answer a hundred questions? I just assumed that would make you go away.\n\nNext time, I'll raise it to a thousand questions.", objectives = "Answer Q'onzu's 100 questions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78169] = { id = 78169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78170] = { id = 78170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurturing Ageless Seeds", description = "The growth of these seeds is a delicate balance, requiring constant nurturing.\n\nI've found that Ageless Dewdrops, gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. \n\nIf you could collect some dewdrops and apply them to the plants, we can unlock their full potential.", progress = "Have you given the Ageless Dewdrops to the blossoming seeds?", completion = "Thank you, {name}. Your willingness to aid in the nurturing of these ancient seeds warms my heart.", objectives = "Nurture each of the seed we planted with Ageless Dewdrops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78171] = { id = 78171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blossoms of the Past", description = "With your help, these seeds have grown into magnificent plants. However, the most exciting part is yet to come.\n\nEach of these plant's blossoms contain a treasure trove of information about their history and the magic that binds them to the world tree. By studying these blossoms, we can better understand the lineage of each plant.\n\nGently collect the blossoms that have fallen and return them to me.", progress = "Have you collected the three blossoms?", completion = "You have done fine work. This may guide you to help restore other plant species from any seeds you may find.", objectives = "Collect 3 Dreamseed Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78172] = { id = 78172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Seeds", description = "<These mysterious seeds might be of interest to Sylvia Whisperbloom.>", completion = "These seeds hold the key to unlocking the legacy of much of the strange flora that was lost in the fires that consumed Teldrassil.", objectives = "Deliver the seeds to Sylvia Whisperbloom at the Wildling Garden.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78177] = { id = 78177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gilneas", description = "The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised.\n\nHowever, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. \n\nJoin me in retaking Gilneas.", progress = "Gilneas will be ours once more.", completion = "Well then, looks like I'm in charge now.\n\nA bit unexpected, but not unwelcome.\n\nVery well. Let's do this.", objectives = "Travel to Keel Harbor in the Ruins of Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78178] = { id = 78178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gilneas", description = "{name}, we've received word of an offensive occurring soon in Gilneas. \n\nWe have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city.\n\nWe wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. \n\nLilian and I want you to join us in this operation.", progress = "Thank you for coming to help, {name}.", completion = "Huh.\n\nI did not expect to be given command.\n\nVery well. Let's do this.", objectives = "Travel to Gilneas in Eastern Kingdoms to assist with retaking Gilneas City for the Gilneans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78180] = { id = 78180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crusade of Red", description = "Calia will lead the Forsaken army in a distracting assault to the North.\n\nI'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops.\n\nThere's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?", progress = "These Scarlets are a blight upon the land.", completion = "The first blow to the Scarlet Crusade was well struck, thanks to you.", objectives = "Kill 10 Scarlet Crusade Members in Aderic's Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78181] = { id = 78181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aderic's Retort", description = "The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. \n\nToo many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner!\n\nTake out their leader, and send them a message they won't soon forget.", progress = "Is she dead, {name}?", completion = "Is it done? Good.", objectives = "Slay Consecrator Hennas in Aderic's Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78182] = { id = 78182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knee-High", description = "Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city.\n\nHead through the tunnel to meet them. Take this torch, the way is infested with vermin. \n\nI'll ready our forces to storm the gate the moment it is opened.", completion = "{name}, right on time.\n\nAre you ready for the next phase of our attack?", objectives = "Make your way through the secret tunnel in Aderic's Repose to Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78183] = { id = 78183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Blood", description = "Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. \n\nWe'll whittle their numbers down one by one.", progress = "Are you done?", completion = "They're all too far gone to be reasoned with. Such a waste of life.", objectives = "Kill 12 Scarlet forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78184] = { id = 78184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokepowder and Mirrors", description = "Opening the gate is all well and good, but we'll need to clear a way for our forces to advance first. Our scouts reported that the Crusade has explosives that they've stashed in the area.\n\nSurely they won't mind if we borrow some?", progress = "Hmm?", completion = "No use squandering perfectly good explosives.", objectives = "Collect 8 Scarlet Explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78185] = { id = 78185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounds of War", description = "I think we've had enough fun on our own, yes? \n\nThe Scarlets stationed near the city's chapel seem to be the most elite of their forces. I believe we'll find whoever is leading them there, but going alone is unnecessarily dangerous.\n\nTime to bring the true might of Gilneas and take our city back. My forces stand ready to charge!", progress = "My people stand ready.", completion = "Now the real fight begins.", objectives = "Open the gates to Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78186] = { id = 78186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crusade", description = "The most powerful members of the Scarlet Crusade will be defending the nest of their leader, {name}. That's where I come in. \n\nNothing like a little distraction to take an enemy down swiftly. Just let me know where and when to strike.", completion = "Good. My troops will clear out the rest of them.", objectives = "Kill 12 Scarlet Crusade members in the Gilneas City chapel courtyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78187] = { id = 78187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artillerist Arsonist", description = "The chapel seems to be their base, and it is well defended--they've set up multiple defenses throughout the courtyard. The troops would have an easier time sieging if we could get some of them out of the way.\n\nRemember those explosives we gathered? Now is when they come in handy.", completion = "That should give our forces some breathing room.", objectives = "Plant 6 explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78188] = { id = 78188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Fire, Righteous Fury", description = "Only one person remains standing between us and our city. Ready yourself--this won't be an easy fight.", progress = "Is she dead?", completion = "We've done it--it will take time to rebuild of course, but Gilneas is ours again! \n\nI can scarcely believe it.", objectives = "Slay the leader of the Scarlet Crusade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78189] = { id = 78189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning a New Dawn", description = "Much has changed since we had to leave this city. Both the land, and my people.\n\nBear witness, {name}, to the future of Gilneas.", completion = "I... I don't know what to say. Thank you, {name}. For everything.", objectives = "Listen to Genn Greymane's conversation with Tess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78190] = { id = 78190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Left Behind", description = "He just... handed me the kingdom.\n\nMe!\n\nThis is going to take a bit to process. But... look, {name}. I know my father's a strong man, but there are times he holds himself so rigid that I fear he'll break. I'm not about to coddle him, but if you could just follow along, make sure he's all right? Soothe a daughter's heart? \n\nA queen's heart?", completion = "Tess sent you, didn't she? That girl... she's clever, determined, and loves just as fiercely as she defends. It's why she is in charge now. \n\nDo not worry over me, {name}. My role in the world is far from over. The Alliance still needs my expertise--and with Gilneas in good hands, I find myself free to fully take on that challenge. Thank you for your concern.\n\nAnd thank you for everything you've done for my kingdom over the years. You are a shining example of skills I am still learning to master myself.", objectives = "Follow King Greymane and keep an eye on him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78203] = { id = 78203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom" }
quests[78206] = { id = 78206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Bounty", description = "There are so many more species to locate and study. As you explore the Dream, you will find more seeds known as Dreamseeds. Please, nurture them to continue our studies, and enjoy the bounty they share with you!\n\nYou will find Dreamseeds all over, but many are hoarded by powerful creatures around the Dream.\n\nAdditionally, you should keep an eye out for the surge of life energy we call an Emerald Frenzy. It will be a source of many Emerald Dewdrops, which will help in nurturing Dreamseeds.", progress = "Have you helped further our research?", completion = "Your efforts are most appreciated. With your help, these plant species may someday be able to return to Azeroth.", objectives = "Partake in the Emerald Frenzy to earn Emerald Dewdrops and contribute a Dreamseed to sprout new growths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78215] = { id = 78215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rooted in Danger" }
quests[78226] = { id = 78226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Intriguing Invitation", description = "We've received an invitation. Or rather, you have, {name}.\n\nIt's a request to meet with the Vizier. That name rattles even the most wealthy and powerful figures in the City of Threads.\n\nGaining this individual as an ally could seal our victory against Ansurek's horrid little shadow for good.\n\nYou're to meet them in the Burrows. Use the pheromone dispenser here in my lair to mask yourself enough to enter safely.", completion = "It surprises me little to see that you've made allies amongst the Kaheti, {name}.\n\nAnd, yes. I'm alive and well. \n\n\n\nNot too much of a shock, I hope?", objectives = "Meet the 'Vizier' in the Burrows of Azj-Kahet's City of Threads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78228] = { id = 78228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into a Skittering City", description = "I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however...\n\nNevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive.\n\nPerhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.", progress = "For being so young, I find Master Anduin is practically bursting with the grand experiences of a much more traveled sort.\n\nImpressive. At least from the perspective of a humble Kaheti.", completion = "Quite the entrance. I should replicate it in the next cabinet meeting.\n\n<Nizrek emits a cough you imagine might be a chuckle.>\n\nPerhaps we should give them a private moment. Whilst we let them have it, would you hear out a small request of mine?", objectives = "Tell the Vizier of the Weaver's plan, and apply Pheromones for access to the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78231] = { id = 78231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like a Spider on the Wall", description = "Inviting Alleria was a risk... but even at this moment, I feel it was worth taking. I know it was.\n\nI will speak with her on my own. In the meantime, I'd like you to venture into the city above. The pheromones Nizrek gifted you will allow access into the Umbral Bazaar. Observe the merchants, listen to the conversations, purchase their goods.\n\nThis city is as vibrant as Stormwind. And its people are as worthy of freeing from abuse as our own. Experience for yourself how similar we all are.", progress = "Enjoy yourself? And no trouble with the pheromones, I hope.", completion = "A vibrant people, such as any other we've encountered together over the decades.\n\nThey deserve that same peace and protection that we seek for our own. \n\nLet us vow that, when forced to fight, it will always be against the source of strife. Never the victims of it.", objectives = "Explore the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78232] = { id = 78232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rewriting the Rewritten", description = "We called you here today because it is \"Ascendance Day\". Queen Ansurek has deigned declare it a day to revel in our newfound, void-infused evolution--our \"Ascendance\". Please note my satirical nuance.\n\nWhile the streets are alive with festivity and joyous citizens, the Shadecasters planted through the Bazaar will be drowning the air with Ansurek's vile propaganda.\n\nTake this invention of mine. Use it to overwrite them with more... illuminating information for the public.", progress = "Anduin has me worried.\n\nI've always known him to lean towards diplomacy, but does he have the conviction to draw his sword?\n\nIf he does not, he may never be able to end this war.", completion = "Yes. The Vizier asked the same of me in the other city districts.\n\nI'll admit that my reluctance to trust Anduin's new ally has waned slightly. No more than a little finger's length, but even that is more than I anticipated.", objectives = "Overwrite 3 Shadecasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78233] = { id = 78233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weaver's Gift", description = "A little weave-rat tells me that an intriguing series of events are playing out to the north. It seems there has been a remarkably coincidental waterfall of failures marring the military efforts there.\n\nI want to know who is responsible. Look into it for me, and see if your curiously binary eyes can pluck out any potential allies.\n\nSome of your little friends are among the escapees drawing the ire of one \"Zev'kall.\" Do go catch up. Tell them the Weaver bids them... greetings.", completion = "We thought we were well hidden.\n\nClearly, not as hidden as we would have liked. But I am grateful to see you, nonetheless.", objectives = "Find the friends the Weaver has revealed to you as a gift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78234] = { id = 78234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Force Your Way", description = "Even with the general gone, it's not going to be easy getting out of here. This place is infested.\n\nI know I'm hiding it well, but I'm not exactly feeling my best. I'm not sure I'll be much help in this state.\n\nYou're going to have to clear a path for us.", progress = "Say what you will, but you do meet the most interesting company while imprisoned.", completion = "In my defense, they disarmed me. And envenomed me. Also, does this look infected to you?\n\nAnyway, if not for all that, I would have helped. You have my word.", objectives = "Kill 8 Kaheti forces in Rak-Zakaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78236] = { id = 78236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrappy Straggler", description = "If someone got left behind, we need to do something about that.\n\nI hate to say it, but these people need someone to protect them here. I have to stay.\n\nFind this straggler. And while you're at it, take a peek behind enemy lines. See if you can find anything useful.", progress = "The others all made it to safety, right?", completion = "I definitely had everything under control.\n\n<Flynn winces.>\n\nBut... I'll admit, this venom is dulling my otherwise lightning-quick reflexes, {name}.", objectives = "Rescue the straggler in Rak-Zakaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78237] = { id = 78237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Fly!", description = "Hm. This Anub'azal gave the orders that led to the prisoners' escape. Zev'kall here didn't seem very pleased with that.\n\nSo how about this--you sneak into Siegehold, and make best friends with Anub'azal. Easy.\n\nI've noticed a lot of cargo being ferried over, I'm sure no one would notice if we just swapped out the contents of a particular crate.\n\nIn the meantime, I'll share our discoveries with the Weaver. I'd love to come with you, but I'd rather not tempt more Flynn stabbings today.", completion = "What an interesting \"delivery\" you are.\n\nI have use for you.", objectives = "Stow away into a box to be carried into Siegehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78244] = { id = 78244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaheti Hospitality", description = "That stage in the distance is where Ansurek will give her Ascendance Day speech.\n\nYou, Alleria, and I shall make our way up one of the nearby towers and observe. If we are to turn her own citizens against her, then we must also gain as much first hand experience with her tactics as we can manage.\n\nI've already told Alleria as much, but we cannot make our presence known. If we do run into any trouble, the Vizier has arranged for a set of getaway fliers at the edge of the Burrows where we first met.", progress = "The Vizier has made special accommodations for us to reach the tower we'll be observing from.\n\nSticking to the plan will mean we all get out safely.", completion = "We made it. Perhaps not as quietly as intended, but alive.", objectives = "Speak to Anduin when you're ready to observe the Ascendance Day speech, and exit the city quietly after.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78248] = { id = 78248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Still Have", description = "I went into the city prepared--prepared to end this war even if I was ended with it.\n\nBut I am alive. As are you. As is Anduin. We have new allies and a new way forward. I realize at this moment that my vision may have been obscured by my guilt.\n\nPart of me feels those words are Anduin's, not mine. Perhaps he's rubbing off on me.\n\nLet us return to your Weaver's Lair. I wish to see yours and Anduin's efforts to save these people as well as our own through.", progress = "I do believe my suggestion was to stay quiet while in the city, was it not?", completion = "How many times were my suspicions diverted from Executor Nizrek's true identity as the \"Vizier?\" Perhaps I've lost my step. Me! A master of spycraft.\n\nHah--far more likely, it is that he's simply much better than I give him credit for.\n\nI find myself quite stirred by the knowledge that someone's gift for subterfuge may rival my own. We shall work together quite nicely.", objectives = "Return to the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78249] = { id = 78249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Specific Personages", description = "Zev'kall has recently placed his own loyal lackeys in key positions around Siegehold. Killing them will force replacements, which will cause chaos and re-training.\n\nAll of which will make Zev'kall struggle. Get rid of all three.", progress = "All three must be removed from office.", completion = "Zev'kall knows that I am involved. I wanted him to know. But he can say nothing, because he is unable to make his own pheromone marks. I have used mine for his needs, so far. \n\nIf he admits he can't, everyone would question his authority... not to mention his status as a nerubian.\n\nIt is quite a scandal.", objectives = "Kill Zev'kall's minions for General Anub'azal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78250] = { id = 78250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Admission", description = "It isn't enough to inconvenience Zev'kall. He should be humiliated. I already have some information, but I need more.\n\nHe stores military logs in a room that is too tiny for me to access. See what information he's hiding. I'm sure there's potential blackmail material in there somewhere.", progress = "There should be something I can use.", completion = "Let me see!\n\nThis... is not blackmail material. But it is far worse.", objectives = "Find some useful blackmail material for the General.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78251] = { id = 78251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran's Most Distressed", description = "I don't trust this big bug at all. He let me lay there ages without saying anything!\n\nBut if he wants to give us access to Siegehold, let's use it. I saw some other people dragged away into other parts of the base. I don't think they're eating them. It looks more like they're transporting them somewhere.\n\nLet's gather them up, make a prisoner convoy, and roll on out. Find me outside!", completion = "Wow... this is a LOT of people.\n\nBut they're all miserable. Fortunately, that's just the flavor we need to sell my idea.\n\nThis could work.", objectives = "Free prisoners for the fake prisoner convoy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78254] = { id = 78254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Influence", description = "These logs of Zev'kall's... he is wasting numerous nerubian lives. Throwing them away like some rabid mantid.\n\nWe must act. As I said, Zev'kall doesn't produce his own pheromone marks anymore due to this 'Ascension' process. He's been forced to use mine. His alchemist is trying to concoct some for him... but once they do, what of me?\n\nTake those false pheromones and sneak them out of Siegehold. Expose Zev'kall, use them... you're creative, aren't you? Just make it messy.", progress = "What did the General ask you to do?", completion = "Smuggle these out? Hmm.\n\nI bet we can use these later, but... if we need to, we'll use them to escape.\n\nHopefully it won't come to that.", objectives = "Steal the pheromones and prepare to sneak them out of Siegehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78255] = { id = 78255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Act Casual", description = "It's time to get outta here with the prisoners and those pheromones. I've found some convincing chains, since we have such a big group. Long as everybody stays in character, our chances look good. \n\nWe've only got General Anub'azal's marker scent goop for you and I, so we'll be the drones with permission. You do all the talkin', while I mind the cart. I hope this works.\n\nLead us through the gate, {name}!", progress = "We just need to make it out of the entrance. I'll figure it out from there.", completion = "Let's take a quick breath. We didn't lose anyone, did we?", objectives = "Help the convoy to exit Siegehold by speaking to the gatekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78256] = { id = 78256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The General's Consensus", description = "We got lucky here. That General Anub'azal is so interested in sabotaging Zev'kall that it's an \"enemy of our enemy is our friend\" situation for today.\n\nI feel like this is gonna be a theme: spiders tryin' to use us against each other. Ah, well.\n\nYou're gonna want to take those pheromones somewhere useful, huh? You do that. I'll take these folks safely out of harm's way.", progress = "What do you have for me?", completion = "What a beautiful gift!\n\nGeneral Anub'azal could be an excellent ally. I'm pleased with your work, morsel.", objectives = "Take Zev'kall's pheromones to someone that has a use for them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78262] = { id = 78262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Starts With a Stone", description = "This land holds so many secrets. And even more power!\n\nAnd you... we both know you enjoy unraveling secrets and collecting marvelous gear. And when you're ready to unlock the power of gear you find in this new land, come visit Cuzolth and me. We are experimenting and will be able to upgrade your gear by the time you come back.\n\nPlease bring me some Flightstones and a new item so I can show you how these upgrades work.", progress = "Can you feel the power? The excitement of knowing you can now take on even more daring adventures?", completion = "Now look at all that shine and glitter! \n\nPlease accept these gifts.", objectives = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 3 equipment using Flightstones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78271] = { id = 78271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreaming of Crests", description = "Now that you've learned the fundamentals, you can easily upgrade lower-level gear.\n\nSooner than later, though, you will find better gear that requires various types of Dreaming Crests to upgrade. Much like Flightstones, these Crests are rewarded through many different activities. Dreaming Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nGo and help with tasks, down formidable foes, find treasures, and bring me a few handfuls of Whelpling's Dreaming Crests!", progress = "I foresee great results with these Dreaming Crests.", completion = "Yes, yes! These crests hold magnificent power. And now so will you.", objectives = "Acquire 15 Whelpling's Dreaming Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Vaskarn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78272] = { id = 78272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interrupting Duck", description = "There are so many bunches of baby bunnies bouncing all about! Ducks have been swarming us and we haven't been able to feed the newborns. You look like you could handle the situation--care to help?", objectives = "Feed carrots to 10 baby bunnies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78274] = { id = 78274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quacking Down", description = "Here they go again. Do you mind scaring off those ducks again? I need to stay here and keep an eye on my golden egg.", progress = "Show those ducks who's boss!", completion = "That'll teach them!", objectives = "Scare off 10 ducks using the Horn of Honking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78289] = { id = 78289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Rambleshire", description = "There's word of troubles in the village of Rambleshire, at the base of Thunderhead Peak. \n\nCan't abide the place myself. Always wet and rumbling.\n\nBut Rooktender Lufsela thought it worth a look, however, seeing as how the birds fancy the moss that the village produces. She's still green though, and might just need a hand.", completion = "Otwin sent you? Probably misses my help brushing out the rooks. But there's something amiss here in Rambleshire.\n\nThere should be a storm overhead. Been visible from Dornogal for as long as I can remember. Without that storm, I fear the local mosswool operation is in trouble.", objectives = "Meet Lufsela in Rambleshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78290] = { id = 78290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleepy Sheep", description = "The energized moss that these flocks produce is a favorite treat for the storm rooks. But with the storm gone, the rams are lethargic, vulnerable, and no longer producing.\n\nWe may not be able to conjure a storm, but we could offer the mosswools a motivating zap. See if you can find a lodestone that will hold a charge. Then bring it here to Shraubendre so she can get it loaded up.", progress = "The lodestone should hold just enough of a charge to give the mosswools the motivation they need to return to their corrals. It won't hurt them.", completion = "The mosswools look like they have a bit more pep. Hopefully they'll start producing again soon, if the storm comes back, that is.\n\nRancher Stenspor believes he knows why the storm is missing. He claims two legendary ram brothers re-energize the storm once a year. Just not this year, for some reason.", objectives = "Use an Energized Lodestone to rouse 8 Lethargic Mosswools near Rambleshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78291] = { id = 78291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Predators", description = "Thunderhead Peak normally boasts a perpetual storm from which the local mosswools draw energy. Without it, the poor dears look to be listless and near dead on their feet. That makes them easy pickings for predators.\n\nTo get moss production back on track, we'll need to get to the bottom of the missing storm. But first we need to beat back these predators before they turn the mosswools to gravel.", progress = "Please do what you can for the poor mosswools.", completion = "That should buy the ranchers and their flocks some time while we figure out what's going on with the missing storm. No storm means no moss, which means grumpy storm rooks.\n\nAccording to the locals, the storm is born of two legendary rams butting heads atop Thunderhead Peak. They think one of them went missing, if you can believe that.", objectives = "Cull 10 predators around Rambleshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78292] = { id = 78292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lord of the Storm", description = "Listen well, stranger. Once a year, the great ram Durzan, Lord of the Southern Storm, crosses the isle to meet his brother Belzt on Thunderhead Peak. The clash of their horns heralds the storm and brings prosperity for another year.\n\nBut something is wrong. Durzan has not come and the skies have cleared. The Stormrider may not believe, but I sense you have seen wilder things.\n\nAsk around if you still have doubts. Just please help us find Durzan.", progress = "Pray Durzan is still with us. If the brothers don't meet at the summit, the storm and our livelihoods will be lost.", completion = "You found him! But why hasn't he gone to the mountain? And why does he look so forlorn?", objectives = "Find Durzan near Rambleshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78293] = { id = 78293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Moss, Our Gain", description = "You say nerubians had him? Not sure what they wanted with old Durzan, but he looks weakened by the ordeal. We can't have that if he's to challenge his brother Belzt on the mountain.\n\nThe moss harvested from our flocks gives the storm rooks a kick, so Durzan might benefit from it as well. Collect a bushel's worth and make an offering.\n\nAnd if the mosswools get ornery, be sure to put them in their place.", progress = "That moss captures and contains the power of the storm. It ought to give Durzan the boost he needs to get back up on that mountain.", completion = "That seemed to do the trick. I think he's ready to return to his brother on Thunderhead Peak.", objectives = "Harvest moss from Rambleshire Mosswools and feed it to Durzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78294] = { id = 78294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhead Butt", description = "Durzan looks hale and hearty again. That moss packs a real punch.\n\nI have a sense that he's ready to go. I just wish we had more time. I have so many questions. But the greatest of those questions will be answered when he reaches the peak.\n\nWe shouldn't send him up there alone. But I think he trusts you to take him.", progress = "We'll be watching from here. I truly hope Belzt is up there waiting.", completion = "The legends were true. The storms, the rooks, and these rams. They're all connected.\n\nI have so much more to learn. But thank you for setting me on this path.", objectives = "Accompany Durzan to Belzt on Thunderhead Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78301] = { id = 78301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalawag Slither", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78302] = { id = 78302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalawag Slither - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78303] = { id = 78303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalawag Slither - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78319] = { id = 78319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Superbloom", description = "Amirdrassil is growing and needs nourishment. Dear old Sprucecrown has a ritual to bloom life around the tree, but our enemies have taken note. We need all the help we can get.\n\nDuring the ritual, Sprucecrown will draw on the magic of the Dream to grow Dreamfruit. Consuming these will grant you amazing powers. Only a few of these powerful and delicious fruits can appear. Keep an eye out for them!\n\nPray lend a hand, hero, and the dream will reward you aplenty.", progress = "Even the tallest of us needs a little help around the roots, now and then.", completion = "Ah, the fresh scent of flowers in the air! \n\nThank you, hero.", objectives = "Participate in the Superbloom and consume the Dreamfruit that appear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78325] = { id = 78325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Dart", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78326] = { id = 78326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Dart - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78327] = { id = 78327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Dart - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78328] = { id = 78328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take a Look Around", description = "The Gala of Gifts is here to showcase the many wonderful artisans carefully crafting gifts just for you and your loved ones.\n\nYou should see what they have to offer, and talk to the other attendees. Who knows, you might just find the perfect gift for someone you care about!", progress = "Have you seen all of the wares available?", completion = "Aren't the wares just marvelous? I find myself just a little jealous of the talent--and I find it hard to resist picking up everything they've made!\n\nDid anything catch your eye?", objectives = "Meet the vendors and visitors at the Gala of Gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78329] = { id = 78329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love is in the Air", description = "Smell these roses! My partner got them for me at the Gala of Gifts.\n\nInterested in seeing things yourself? Head to the gates of Stormwind. There are gifts, and food, and you should taste the chocolate, it's delicious!", completion = "Welcome to the Gala of Gifts, friend!\n\nWould you like to hear more about our specialty chocolates?", objectives = "Visit the Gala of Gifts at the gates of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78332] = { id = 78332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Smell Trouble", description = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it?\n\nWell, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away!\n\nAre you in? I could use a good partner to solve this.", progress = "Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", completion = "Poisonous perfumes? Revenge for kicking 'em out of the city?\n\nSeems like Apothecary Hummel is cooking up something sinister again. But deadly poisons? Sheesh, this could get ugly.", objectives = "Use O.D.I.E.'s Remote Control to find clues around Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78334] = { id = 78334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Burble", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78335] = { id = 78335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Burble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78336] = { id = 78336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Burble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78337] = { id = 78337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Gift", description = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent!\n\nBut let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", progress = "Follow your nose, pal! Anyone who stinks could be a suspect.", completion = "Yeesh, {name}, you reek!\n\n\n\nEven worse! I reek!\n\nWell at least we've given some peace to the gala. I'd hate to have the Crown ruining the celebrations.", objectives = "Kill 8 Crown Chemical Co. members around Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78346] = { id = 78346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak Zephyr", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78347] = { id = 78347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak Zephyr - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78348] = { id = 78348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Low Places", description = "When we crashed, the nerubians were upon us in an instant. We would have lost nearly everyone we brought with us, had someone not intervened.\n\nI do not know who--or what--stepped in on our behalf. But if there is even a shred of hope that we have allies in this place then we must seize upon it and refuse to let go.", completion = "Ah! You survived. Excellent. You have much to do.", objectives = "Search the Breathing Pit for your mysterious protector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78349] = { id = 78349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak Zephyr - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78350] = { id = 78350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes Never Die", description = "Damn it all! We were too hasty, and now my people are paying the price.\n\nWe were fools to think the nerubians wouldn't be prepared for an incursion. Arathi soldiers are made of stern stuff, but even they will struggle to walk off an airship crash.\n\nI will keep everyone here safe. Please, go into the field and rescue as many people as you can.", progress = "Make haste, {class}. Time is of the essence.", completion = "I thank you, {name}, on behalf of those you saved. No one deserves to die alone in the dark, least of all in a place like this.", objectives = "Aid twelve Wounded Aeroknights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78352] = { id = 78352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Naught, So Vial", description = "Truthfully, I don't care what the nerubians are plotting. They are not the first upstart people seeking power, and they certainly won't be the last. The problem is how they're going about it. I fear that tampering with this Black Blood will threaten far more than the delicate ecosystems of Khaz Algar.\n\nWe must make sure that they never return to this pit again. Their equipment is still strewn throughout the pit. Destroy as much of it as you can manage.", progress = "The nerubians fled when those aberrations began appearing en masse, but I imagine they will try to come back for their ill-advised treasures. We need to make sure they have nothing to come back for.", completion = "<Orweyna scowls.>\n\nThe nerubians are a bold people, but this seems extreme, even for them.", objectives = "Destroy 8 pieces of nerubian extracting equipment throughout the Breathing Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78353] = { id = 78353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear the Old Blood", description = "This is not exactly the place for a long talk, so I will be brief.\n\nThese roots you see are part of something much greater than you know, and it is my job to protect them. \n\nIf it isn't obvious to you already, this place is teeming with writhing Black Blood. If we do not act, it will spread deeper and further still.\n\nYou want allies? Fine. Help me cleanse this place and protect these roots, and I will at least hear you out.", completion = "Between your sweat and my spellwork, we've managed to at least contain the problem to this blighted cavern.\n\nStill, what a disaster. If this is what one cave of the stuff can do, I shudder to think what the nerubians might do with more of it.", objectives = "Work to cleanse the Breathing Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78354] = { id = 78354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Guiding Thread", description = "<The words on the parchment appear burned, not written. A venomous tang singes your nose.>\n\nBlind and alone, you stumble in the dark. I offer you a thread to cling to.\n\nFollow it, should you wish to find your allies.", progress = "State your business, lest I get peckish.", completion = "So you followed my guiding line to its terminus. \n\nFor both of our sakes, I am glad that your zeal outpaces your survival instinct.", objectives = "Follow Spindle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78355] = { id = 78355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of a Broken Dream", description = "<You feel an echo of ancient sorrow, fear, and rage as you gaze into the swirling depths of this strange sphere. Maybe Merithra will know more about it?>", completion = "Interesting... I sense poor Gnarlroot's ancient hopes and dreams within, but darkened and twisted by Igira's depraved cruelties. It's as if the Dream itself tried to isolate her efforts in this essence.", objectives = "Find Merithra in Amirdrassil, the Dream's Hope, and show her the Twisted Dreaming Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78357] = { id = 78357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamy Drakewatching" }
quests[78358] = { id = 78358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake's Crests", objectives = "Your assistance has been paramount in revitalizing the Dream. Please accept this as a reward for your efforts. Thank you for all your hard work, champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78363] = { id = 78363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tabard of Your Dreams", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we are immensely grateful for all you've done to help us. Please meet me at Central Encampment so we can properly reward you for your efforts!\n\n- Amrymn", completion = "You have more than earned this tabard. Is it all that you have dreamed it would be?", objectives = "Talk to Keeper Amrymn at the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78364] = { id = 78364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake's Crests", objectives = "Your assistance has been paramount in revitalizing the Dream. Please accept this as a reward for your efforts. Thank you for all your hard work, champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78369] = { id = 78369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver.\n\n<Snagglebolt points to the unmarked box.>\n\nBombs. I got bombs.\n\nPlaytime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", progress = "We need to put a stop to this before the Crown pulls off their smelly sabotage.", completion = "Man, I love a good fireworks show! Great job, {name}. That oughta slow them down.\n\nNow there's just Hummel to deal with.", objectives = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78370] = { id = 78370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws for Concern" }
quests[78372] = { id = 78372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake's Crests", objectives = "Your assistance has been paramount in revitalizing the Dream. Please accept this as a reward for your efforts. Thank you for all your hard work, champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78373] = { id = 78373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dream Thanks You", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, your contributions to the dream are immeasurable. Please meet me at the Central Encampment, we have a reward we're excited to give you.\n\n- Amrymn", completion = "Thank you. For everything.", objectives = "Talk to Amrymn in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78374] = { id = 78374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightstones", objectives = "Your assistance has been paramount in revitalizing the Dream. Please accept this as a reward for your efforts. Thank you for all your hard work, champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78377] = { id = 78377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counting Drakes" }
quests[78379] = { id = 78379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stench of Revenge", description = "We're never gonna see an end to this unless we take on the boss himself.\n\nLook, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Stormwind if we let him finish his research.\n\nYou go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", progress = "You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", completion = "Sounds like you got there just in time--great work.\n\nThis would have gotten real ugly if Hummel poisoned the entire gala.\n\nLet's just call this our gift to them, eh?", objectives = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78380] = { id = 78380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Dream of Drakes" }
quests[78381] = { id = 78381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreams Unified", description = "Another incredible find, {name}!\n\nThis half of a Spark of Dreams could prove useful in your crafting endeavors if you could unite it with a sister piece.\n\nSet out in search of another Splintered Spark of Dreams and combine them.", progress = "Have you located another Splintered Spark of Dreams?", completion = "That's great news! As you find more you can continue to combine them to benefit your crafted gear.", objectives = "Find another Splintered Spark of Dreams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78383] = { id = 78383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Edge", description = "To add insult to injury, they disarmed me. I'm not leaving without those blades!\n\nWhile we're looking, keep an eye out for any evidence of what's going on here. Anything that could give us an advantage against the nerubians.\n\nSomething strange happened that provided us the opening to escape. I have a feeling that could be something we can exploit.", progress = "There must be something around here of value to the Weaver...", completion = "This seems like enough to trade to the Weaver for that antidote. Anub'azal is a good lead to investigate. Maybe he'll barter like the Weaver did, and we'll get something even better from him.\n\nIt sounds like a good risk to me.", objectives = "Find Flynn's Blades and 3 nerubian intel from Kaheti forces in Rak-Zakaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78384] = { id = 78384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Light", description = "Anduin survived that swarm. I do not doubt that for a moment. Even so, the nerubians are everywhere and he is just one man.\n\nWherever he goes, wherever he is taken, I will find him. Find me any sign that he yet lives. That is all I need to follow him to Azeroth's end.", progress = "You've returned.\n\nI trust you have news.", completion = "A shattered gauntlet and some scraps of cloth... but no corpse. That's good, at least. He's alive, and he fought back.\n\nStill, it's not much to go on. Most rangers would be understandably stumped.\n\nLuckily, I am not most rangers.", objectives = "Search for clues of Anduin's survival.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78385] = { id = 78385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", completion = "Please accept these Dreamseeds as a thank you for all you've done.", objectives = "Talk to Sylvia Whisperbloom in [zone].", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78386] = { id = 78386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Reawakening", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we found a way to bring creatures into the dream. Speak to me if you'd like to know more!\n\n- Elianna", completion = "To do a thing, you must first dream it.", objectives = "Talk to Elianna in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78387] = { id = 78387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plump Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", completion = "Please accept these dreamseeds as a thank you for all you've done.", objectives = "Talk to [NPC] in [zone].", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78388] = { id = 78388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantic Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", completion = "Please accept these dreamseeds as a thank you for all you've done.", objectives = "Talk to [NPC] in [zone].", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78389] = { id = 78389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Makers' Marathon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78390] = { id = 78390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Makers' Marathon - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78391] = { id = 78391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Makers' Marathon - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78392] = { id = 78392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tangled Web", description = "Make no mistake--I have no intention of sending you off to skitter about in the dark like a freshly-hatched beetle. It wouldn't do to have my little morsel snatched up by a starving cave borer.\n\nYou must educate yourself, my dear. Your allies have found themselves ensconced in a torrid tapestry. Only by familiarizing yourself with its erstwhile architects can you hope to reclaim them.\n\nLuckily for you, I have made some of my personal resources available to you.", progress = "Haven't you finished yet? Really, the archives' design is quite elegant. Just tap and listen. Even a spindly thing like you can figure it out, I am sure.", completion = "Now you see how the stage has been set. You have arrived in the middle of the play, I fear--but you needn't worry! You've time yet to play a most vital role.", objectives = "Peruse the Weaver's archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78393] = { id = 78393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seeming Respite", description = "You have endured quite the evening since your ill-fated little ship ride, haven't you? Worry not, little morsel. You will find that my friends here are most accommodating, even to someone with your predilections--as strange as they may be.\n\nPlease, take a moment to explore. Avail yourself of my many amenities. With luck, you will find some sorely-needed rest.\n\n...Oh, but do take care not to move about too quickly. Sudden movements, I'm sure you understand.", progress = "There is no need to be afraid! I am almost certain my companions will not eat you.", completion = "Well? Are you not impressed with my hospitality?", objectives = "Explore the Lair of the Weaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78398] = { id = 78398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dash of Minerals...", description = "I think we have a chance with this one, {name}. But we'll need to begin revitalizing the soil if we want to see this plant flourish.\n\nHead to the Eye of Ysera and harvest fish bones from the Fathomless Lurkers in the depths of the water. They're rich in minerals and degrade easily. It won't replenish the soil on its own, but it's a great start.", progress = "Did you have a chance to pick up what I asked for? This plant won't thrive without it.", completion = "That's the stuff. I appreciate you taking the trouble to collect them. \n\nThis form isn't optimal for swimming, you understand.", objectives = "Collect Fish Bones from Fathomless Lurkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78421] = { id = 78421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Dreams", description = "It seems that the fabric of the Emerald Dream itself is rejecting the invaders, leaving behind shadows of their dreams in the form of these Essences. So close to Amirdrassil, even your own actions are leaving behind ephemeral echoes of power. \n\nWith enough time, perhaps we can use these echoes to awaken their strength and turn it against Fyrakk himself. Defeat the invaders wherever you find them and return to me when you have gathered enough of the Dream's power.", progress = "The Dream has many layers, some quite fragile. I worry that even the defenders' presence will change the unchanging land.", completion = "This will be sufficient to awaken the dormant power within these fiery essences. Finally, we are ready to turn the invaders' power against them.", objectives = "Gather Echoed Ephemera and the Dreams of the Invaders of Amirdrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78427] = { id = 78427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Crates!", description = "The assault on the Dream grows ever stronger.\n\nWe are in desperate need of trade goods and supplies to support the defense effort. Even just one crate could make the difference on the front line.\n\nVashonir can assist you with packing the shipments. Then bring the shipment to me.\n\nElune watch over you, defender of the Dream.", progress = "Vashonir will assist in preparing the shipments for you.", completion = "We are ever more grateful for your contributions.", objectives = "Pack 1 Shipment of Goods with Vashonir in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78428] = { id = 78428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crate of the Art", progress = "Be sure to ask Vashonir to help you prepare the shipments!", completion = "Thank you, {name}. We are ever in your debt.", objectives = "Pack 5 Shipments of Goods with Vashonir in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78429] = { id = 78429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Dreams, Awoken", description = "Are you ready, {name}? I will fuse the essences of their fiery dreams together for you. Focus the Echoed Ephemera you have collected to awaken the latent power within. Show Fyrakk that even he should fear the power of the Dream!", objectives = "Awaken the power within the Fused Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78430] = { id = 78430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mean Green Infusion Machine", description = "Pleased to meet you. I am Elianna, a Dream Researcher.\n\nA strange phenomenon has recently been detected in the Dream. Fragments of dream magic are being left behind by the creatures here.\n\nI'm curious to know the effects of such magic in concentrated doses. But I need someone to extract it for me.\n\nThere are some problematic lashers and podlings to the south of here. \n\nSeveral of them should be enough for a lesser infusion.", progress = "Have you brought me enough Dream energy?", completion = "Excellent! We should be able to perform the infusion!", objectives = "Kill 6 podlings and lashers in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78431] = { id = 78431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Dream Team", description = "Most interesting! \n\nI was able to concentrate the Dream energy you brought me. \n\nWith this, we can perform the infusion!\n\nGo ahead, I'll watch.", progress = "Go on! I want to see you infuse Rithro.", completion = "Amazing! It worked!", objectives = "Perform a Lesser Dream Infusion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78434] = { id = 78434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonrider Racing - Ysera Invitational" }
quests[78435] = { id = 78435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonrider Racing - Smoldering Sprint" }
quests[78436] = { id = 78436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonrider Racing - Viridescent Venture" }
